/* ---- consolidated patch block: drag-vs-tap ---- */
__sxInit(function () {
// Fix 2 (Build 2026-10-17_2309): drag-vs-tap disambiguation.
// A pointerup >10px from its pointerdown suppresses the subsequent click,
// so panning across the center hub no longer pops the rating dialog.
(function(){
  var downX=0, downY=0, downT=0, suppress=false;
  document.addEventListener('pointerdown', function(e){
    downX=e.clientX; downY=e.clientY; downT=Date.now(); suppress=false;
  }, true);
  document.addEventListener('pointerup', function(e){
    var dx=e.clientX-downX, dy=e.clientY-downY;
    suppress = (dx*dx+dy*dy) > 100; /* 10px squared */
  }, true);
  document.addEventListener('click', function(e){
    if(suppress){ e.stopPropagation(); e.preventDefault(); suppress=false; }
  }, true);
})();
});

/* ---- consolidated patch block: map-touch-selection-guard ---- */
__sxInit(function () {
// Fix (Build 2026-10-19_1525): Pixel touch lockup — a translucent blue
// rectangle stuck over the center of the map and the map dead to touch.
// That box is the browser's native content-selection highlight. The
// center node's hit target opted out of the map's touch contract
// (.center-hit carried touch-action:manipulation while #mapSvg requires
// touch-action:none), the map's tap handler for touch on the center
// returns without preventDefault or pointer capture, and nothing stopped
// a selection from starting inside the SVG — a triple-tap on the center
// node is Chrome Android's select-block gesture, so the browser painted
// the selection box anchored on the center node and kept every later
// touch for selection adjustment instead of delivering it to the map.
// With the gesture sequence swallowed, the app's active-pointer state
// could also be left holding a pointer that would never report again
// (the wedge class fixed for the About-dialog path in Build
// 2026-10-18_1305). The .center-hit and .center-glance-ring-hit rules
// now use touch-action:none like the rest of the map,
// the trailing stylesheet forces user-select:none across the whole SVG
// subtree, and this guard refuses selection / drag / context-menu
// takeovers that start on the map and clears any selection that already
// exists when a new press lands on the map, so a stuck box dismisses on
// the next touch instead of wedging the map.
(function(){
  function inMap(e){
    var t=e&&e.target;
    return !!(t&&t.closest&&t.closest("#mapSvg"));
  }
  function clearSelection(){
    try{
      var s=window.getSelection&&window.getSelection();
      if(s&&!s.isCollapsed)s.removeAllRanges();
    }catch(err){ if(typeof __sxErrLog==="function")__sxErrLog("map-selection-clear",err); }
  }
  document.addEventListener("selectstart",function(e){ if(inMap(e))e.preventDefault(); },true);
  document.addEventListener("dragstart",function(e){ if(inMap(e))e.preventDefault(); },true);
  document.addEventListener("contextmenu",function(e){ if(inMap(e))e.preventDefault(); },true);
  document.addEventListener("pointerdown",function(e){ if(inMap(e))clearSelection(); },true);
  document.addEventListener("touchstart",function(e){ if(inMap(e))clearSelection(); },{capture:true,passive:true});
})();
});

/* ---- consolidated patch block: map-selection-dim ---- */
__sxInit(function () {
// Branch selection dimming (Build 2026-10-19_1535): when a branch or
// section is selected — its spoke carries .selected-spoke — the map dims
// everything else so the selection reads at a glance. This block only
// mirrors the render state into classes: .has-selection on #mapSvg and
// .sel-keep on each selected branch's node group and its matching spoke
// underlay; the stylesheet rules beside the 1525 guard do the dimming.
// Purely visual — unlike the touch-selection guard above (which refuses
// native text selection on the map), nothing here touches selection
// gestures, hit targets, or the .selected-spoke highlight path itself.
(function(){
  var svg=document.getElementById("mapSvg");
  if(!svg)return;
  var queued=false;
  function syncSelectionDim(){
    var spokes=svg.querySelectorAll(".selected-spoke"), i;
    if(!spokes.length){
      svg.classList.remove("has-selection");
      var stale=svg.querySelectorAll(".sel-keep");
      for(i=0;i<stale.length;i++)stale[i].classList.remove("sel-keep");
      return;
    }
    svg.classList.add("has-selection");
    var keep=[];
    for(i=0;i<spokes.length;i++){
      var g=spokes[i].closest?spokes[i].closest(".node-group"):null;
      if(!g)continue;
      if(keep.indexOf(g)===-1)keep.push(g);
      var key=g.getAttribute("data-layout-key");
      if(key){
        var u=svg.querySelector('.spoke-underlay-item[data-spoke-for="'+key+'"]');
        if(u&&keep.indexOf(u)===-1)keep.push(u);
      }
    }
    var marked=svg.querySelectorAll(".sel-keep");
    for(i=0;i<marked.length;i++){
      if(keep.indexOf(marked[i])===-1)marked[i].classList.remove("sel-keep");
    }
    for(i=0;i<keep.length;i++)keep[i].classList.add("sel-keep");
  }
  function schedule(){
    if(queued)return;
    queued=true;
    requestAnimationFrame(function(){ queued=false; syncSelectionDim(); });
  }
  new MutationObserver(schedule).observe(svg,{childList:true,subtree:true});
  syncSelectionDim();
})();
});

