/* ---- consolidated patch block: guide-qmark-gestures ---- */
__sxInit(function () {
/* HEADER-QMARK (2026-11-02): tap-count gestures on the header "?" mark
   (#reviewLink, the guide door beside the header avatar) ONLY.
   One tap/click opens the Guide (the door's existing job, same
   destination); two quick taps or a double-click open the program's
   About dialog (the same dialog the title tap opens); five quick taps
   or clicks spring the Easter egg (the same Linktree reveal the title's
   five-click trigger fires). Discrimination: a single opens the Guide
   only after the window elapses with no second tap; a double never
   opens the Guide; five opens NEITHER the Guide NOR the About; counts
   reset after each gesture resolves. Touch taps and mouse clicks both
   arrive as click events on the anchor, so one click listener counts
   both. The title trigger, the rings, and the avatar are untouched. */
(function () {
  var link = document.getElementById("reviewLink");
  if (!link) return;
  var WINDOW_MS = 400;
  var count = 0;
  var timer = null;
  function reset() {
    count = 0;
    if (timer) { clearTimeout(timer); timer = null; }
  }
  function openGuide() {
    window.open(link.href, "_blank", "noopener");
  }
  function openAbout() {
    var o = document.getElementById("openAppAbout");
    if (o) o.click();
  }
  function openEasterEgg() {
    var egg = document.querySelector(".easter-egg");
    if (egg) { egg.click(); return; }
    window.open("https://linktr.ee/SkewedViewBlue", "_blank", "noopener");
  }
  function resolveGesture() {
    var n = count;
    reset();
    if (n === 1) openGuide();
    else if (n === 2) openAbout();
    /* 3 or 4 quick taps resolve to nothing: only 1, 2, and 5 act. */
  }
  link.addEventListener("click", function (event) {
    event.preventDefault();
    count += 1;
    if (count >= 5) {
      reset();
      openEasterEgg();
      return;
    }
    if (timer) clearTimeout(timer);
    timer = setTimeout(resolveGesture, WINDOW_MS);
  });
})();
});

